import React, { useState } from 'react';
import { Search, ChevronDown, ChevronRight, Plus } from 'lucide-react';
import clsx from 'clsx';

export interface MergeTag {
  tag: string;
  label: string;
  desc?: string;
}

interface SidebarProps {
  standardVars: MergeTag[];
  customVars: MergeTag[];
  onInsert: (tag: string) => void;
}

export const PersonalizationSidebar: React.FC<SidebarProps> = ({ standardVars, customVars, onInsert }) => {
  const [search, setSearch] = useState('');
  const [expanded, setExpanded] = useState<Record<string, boolean>>({
    standard: true,
    custom: true,
    sender: true,
    sequence: true,
    fallback: false,
  });

  const [fallbackField, setFallbackField] = useState('first_name');
  const [fallbackValue, setFallbackValue] = useState('there');

  const toggleSection = (section: string) => {
    setExpanded(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const senderVars: MergeTag[] = [
    { tag: '{{sender_name}}', label: 'Sender Name', desc: 'Name from sending account' },
    { tag: '{{sender_email}}', label: 'Sender Email', desc: 'Email address of sender' },
    { tag: '{{sender_company}}', label: 'Sender Company', desc: 'Company of sender' },
    { tag: '{{sender_title}}', label: 'Sender Title', desc: 'Job title of sender' },
    { tag: '{{signature}}', label: 'Signature', desc: 'Signature block configured on account' },
  ];

  const sequenceVars: MergeTag[] = [
    { tag: '{{sequence_name}}', label: 'Sequence Name', desc: 'Name of the current sequence' },
    { tag: '{{step_number}}', label: 'Step Number', desc: 'Current step number' },
  ];

  const filterVars = (vars: MergeTag[]) => {
    if (!search) return vars;
    const lower = search.toLowerCase();
    return vars.filter(v => v.label.toLowerCase().includes(lower) || v.tag.toLowerCase().includes(lower));
  };

  const filteredStandard = filterVars(standardVars);
  const filteredCustom = filterVars(customVars);
  const filteredSender = filterVars(senderVars);
  const filteredSequence = filterVars(sequenceVars);

interface SectionProps {
  title: string;
  id: string;
  vars: MergeTag[];
  isExpanded: boolean;
  onToggle: () => void;
  onInsert: (tag: string) => void;
}

const Section: React.FC<SectionProps> = ({ title, id, vars, isExpanded, onToggle, onInsert }) => {
  if (vars.length === 0) return null;

  return (
    <div className="border-b border-gray-700">
      <button
        type="button"
        onClick={onToggle}
        className="w-full flex items-center justify-between py-3 px-4 text-sm font-medium text-gray-200 hover:bg-gray-800 transition-colors"
      >
        {title}
        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
      </button>
      {isExpanded && (
        <div className="px-4 pb-3 space-y-2">
          {vars.map(v => (
            <div
              key={v.tag}
              onClick={() => onInsert(v.tag)}
              className="group flex flex-col p-2 rounded-md hover:bg-gray-800 cursor-pointer transition-colors border border-transparent hover:border-gray-700"
            >
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-gray-200">{v.label}</span>
                <Plus size={14} className="text-gray-500 opacity-0 group-hover:opacity-100 transition-opacity" />
              </div>
              <span className="text-xs text-indigo-400 font-mono mt-1">{v.tag}</span>
              {v.desc && <span className="text-xs text-gray-500 mt-0.5 line-clamp-1">{v.desc}</span>}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

  const handleInsertFallback = () => {
    onInsert(`{{${fallbackField}|${fallbackValue}}}`);
  };

  return (
    <div className="w-80 border-l border-gray-700 bg-gray-900 flex flex-col h-full overflow-hidden shrink-0">
      <div className="p-4 border-b border-gray-700">
        <h3 className="text-sm font-semibold text-gray-100 mb-3">Personalization</h3>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 w-4 h-4" />
          <input
            type="text"
            placeholder="Search variables..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-gray-800 border border-gray-700 rounded-md text-sm text-gray-200 placeholder-gray-500 focus:outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        <Section title="Contact Fields" id="standard" vars={filteredStandard} isExpanded={expanded['standard']} onToggle={() => toggleSection('standard')} onInsert={onInsert} />
        <Section title="Custom Fields (CSV)" id="custom" vars={filteredCustom} isExpanded={expanded['custom']} onToggle={() => toggleSection('custom')} onInsert={onInsert} />
        <Section title="Sender Fields" id="sender" vars={filteredSender} isExpanded={expanded['sender']} onToggle={() => toggleSection('sender')} onInsert={onInsert} />
        <Section title="Sequence Fields" id="sequence" vars={filteredSequence} isExpanded={expanded['sequence']} onToggle={() => toggleSection('sequence')} onInsert={onInsert} />

        <div className="border-b border-gray-700">
          <button
            type="button"
            onClick={() => toggleSection('fallback')}
            className="w-full flex items-center justify-between py-3 px-4 text-sm font-medium text-gray-200 hover:bg-gray-800 transition-colors"
          >
            Smart Fallbacks
            {expanded['fallback'] ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
          </button>
          {expanded['fallback'] && (
            <div className="px-4 pb-4 space-y-3">
              <p className="text-xs text-gray-400 leading-relaxed">
                If a contact is missing data, show a fallback word instead of a blank space.
              </p>

              <div className="space-y-2">
                <div>
                  <label className="text-xs font-medium text-gray-400 block mb-1">Variable Name</label>
                  <input
                    type="text"
                    value={fallbackField}
                    onChange={e => setFallbackField(e.target.value)}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-2 py-1.5 text-sm text-gray-200 focus:outline-none focus:border-indigo-500"
                    placeholder="e.g. first_name"
                  />
                </div>
                <div>
                  <label className="text-xs font-medium text-gray-400 block mb-1">Fallback Value</label>
                  <input
                    type="text"
                    value={fallbackValue}
                    onChange={e => setFallbackValue(e.target.value)}
                    className="w-full bg-gray-800 border border-gray-700 rounded px-2 py-1.5 text-sm text-gray-200 focus:outline-none focus:border-indigo-500"
                    placeholder="e.g. there"
                  />
                </div>
              </div>

              <div className="bg-gray-800 p-2 rounded-md border border-gray-700">
                <span className="text-xs text-gray-400 block mb-1">Resulting Tag:</span>
                <span className="text-sm text-indigo-400 font-mono">{`{{${fallbackField}|${fallbackValue}}}`}</span>
              </div>

              <button
                type="button"
                onClick={handleInsertFallback}
                className="w-full py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium rounded transition-colors"
              >
                Insert Fallback
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { templateService } from '../../services/template.service';
import { emailAccountService } from '../../services/emailAccount.service';
import { importService } from '../../services/import.service';
import type { EmailConnection, ImportList, ImportedContact } from '../../types';
import { Loader2, Mail, AlertTriangle } from 'lucide-react';

interface PreviewPanelProps {
  subject: string;
  bodyHtml: string;
}

export const PreviewPanel: React.FC<PreviewPanelProps> = ({ subject, bodyHtml }) => {
  const [connections, setConnections] = useState<EmailConnection[]>([]);
  const [selectedConnection, setSelectedConnection] = useState<string>('');

  const [importLists, setImportLists] = useState<ImportList[]>([]);
  const [selectedList, setSelectedList] = useState<string>('');

  const [contacts, setContacts] = useState<ImportedContact[]>([]);
  const [selectedContact, setSelectedContact] = useState<string>('');

  const [previewData, setPreviewData] = useState<{ subject: string; html: string } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [validation, setValidation] = useState<{ valid: boolean; warnings: string[]; errors: string[] } | null>(null);

  // Load initial data (Connections & Import Lists)
  useEffect(() => {
    emailAccountService.list().then(res => {
      setConnections(res);
      if (res.length > 0) setSelectedConnection(res[0]._id);
    });
    importService.list().then(res => {
      setImportLists(res || []);
      if (res && res.length > 0) {
        setSelectedList(res[0]._id);
      }
    });
  }, []);

  // Load contacts when list changes
  useEffect(() => {
    if (selectedList) {
      importService.get(selectedList).then(res => {
        setContacts(res.contacts || []);
        if (res.contacts && res.contacts.length > 0) {
          setSelectedContact(res.contacts[0]._id);
        } else {
          setSelectedContact('');
        }
      });
    }
  }, [selectedList]);

  // Fetch Preview Render & Validation when dependencies change
  useEffect(() => {
    const fetchPreview = async () => {
      setIsLoading(true);
      try {
        // Validate
        const valRes = await templateService.validateTemplate({
          subject,
          body_html: bodyHtml,
          email_connection_id: selectedConnection || undefined,
        });
        setValidation(valRes);

        // Render Preview
        const previewRes = await templateService.previewRender({
          subject,
          body_html: bodyHtml,
          contact_ids: selectedContact ? [selectedContact] : [],
          email_connection_id: selectedConnection || undefined,
        });

        if (previewRes.length > 0) {
          setPreviewData({ subject: previewRes[0].subject, html: previewRes[0].html });
        }
      } catch (err) {
        console.error('Failed to preview', err);
      } finally {
        setIsLoading(false);
      }
    };

    // Debounce preview fetch to avoid spamming the API while typing if this was live, 
    // but typically Preview mode is static until the user changes selection.
    const timer = setTimeout(() => {
      fetchPreview();
    }, 500);

    return () => clearTimeout(timer);
  }, [subject, bodyHtml, selectedContact, selectedConnection]);

  return (
    <div className="flex flex-col h-full bg-gray-50 overflow-hidden">
      {/* Top Context Bar */}
      <div className="bg-white border-b border-gray-200 px-6 py-4 grid grid-cols-2 gap-4 shrink-0 shadow-sm z-10">
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1 uppercase tracking-wider">Sender Account</label>
          <select
            value={selectedConnection}
            onChange={e => setSelectedConnection(e.target.value)}
            className="w-full text-sm border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 bg-gray-50 py-2 pl-3 pr-8"
          >
            <option value="">-- No sender context --</option>
            {connections.map(c => (
              <option key={c._id} value={c._id}>{c.label} ({c.from_email})</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1 uppercase tracking-wider">Recipient (Contact)</label>
          <div className="flex gap-2">
            <select
              value={selectedList}
              onChange={e => setSelectedList(e.target.value)}
              className="flex-1 text-sm border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 bg-gray-50 py-2 pl-3 pr-8"
            >
              <option value="">-- No list --</option>
              {importLists.map(l => (
                <option key={l._id} value={l._id}>{l.name}</option>
              ))}
            </select>
            <select
              value={selectedContact}
              onChange={e => setSelectedContact(e.target.value)}
              className="flex-1 text-sm border-gray-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 bg-gray-50 py-2 pl-3 pr-8"
              disabled={!selectedList}
            >
              <option value="">-- Mock Data --</option>
              {contacts.map(c => (
                <option key={c._id} value={c._id}>{c.mapped_data.email}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Validation Banner */}
      {validation && (validation.errors.length > 0 || validation.warnings.length > 0) && (
        <div className="px-6 py-3 bg-white border-b border-gray-200 shrink-0">
          {validation.errors.map((err, i) => (
            <div key={i} className="flex items-start text-sm text-red-600 mb-1">
              <AlertTriangle className="w-4 h-4 mr-2 mt-0.5 shrink-0" />
              <span>{err}</span>
            </div>
          ))}
          {validation.warnings.map((warn, i) => (
            <div key={i} className="flex items-start text-sm text-yellow-600 mb-1">
              <AlertTriangle className="w-4 h-4 mr-2 mt-0.5 shrink-0" />
              <span>{warn}</span>
            </div>
          ))}
        </div>
      )}

      {/* Email Rendering Frame */}
      <div className="flex-1 overflow-y-auto p-6 bg-gray-100 flex justify-center">
        <div className="w-full max-w-3xl bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden flex flex-col h-fit min-h-[400px]">

          <div className="border-b border-gray-100 px-6 py-4 bg-white flex flex-col gap-2 shrink-0">
            <div className="flex items-center gap-2 text-gray-500 text-sm">
              <span className="font-medium w-12">From:</span>
              <span className="text-gray-900 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">
                {selectedConnection ? connections.find(c => c._id === selectedConnection)?.from_name : 'Sender Name'} &lt;{selectedConnection ? connections.find(c => c._id === selectedConnection)?.from_email : 'sender@example.com'}&gt;
              </span>
            </div>
            <div className="flex items-center gap-2 text-gray-500 text-sm">
              <span className="font-medium w-12">To:</span>
              <span className="text-gray-900 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">
                {selectedContact ? contacts.find(c => c._id === selectedContact)?.mapped_data.email : 'contact@example.com'}
              </span>
            </div>
            <div className="flex items-center gap-2 text-gray-500 text-sm mt-2 border-t border-gray-100 pt-2">
              <span className="font-medium w-12">Subject:</span>
              {isLoading ? (
                <div className="h-4 bg-gray-200 rounded w-64 animate-pulse"></div>
              ) : (
                <span className="text-gray-900 font-semibold">{previewData?.subject || '(no subject)'}</span>
              )}
            </div>
          </div>

          <div className="p-6 text-gray-800 text-sm md:text-base leading-relaxed flex-1 relative bg-white prose max-w-none">
            {isLoading && (
              <div className="absolute inset-0 bg-white/60 flex items-center justify-center z-10 backdrop-blur-sm">
                <Loader2 className="w-8 h-8 animate-spin text-indigo-500" />
              </div>
            )}

            {previewData?.html ? (
              <div dangerouslySetInnerHTML={{ __html: previewData.html }} />
            ) : (
              !isLoading && <p className="text-gray-400 italic">No content to display</p>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

