import React, { useEffect, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { X, Eye, Edit2 } from 'lucide-react';
import { Input } from '../ui/Input';
import type { Template, CreateTemplateDto } from '../../types';
import { templateService } from '../../services/template.service';

import { TipTapEditor } from './TipTapEditor';
import { PersonalizationSidebar, MergeTag } from './PersonalizationSidebar';
import { PreviewPanel } from './PreviewPanel';

interface TemplateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: CreateTemplateDto) => Promise<void>;
  initialData?: Template | null;
}

const templateSchema = z.object({
  name:      z.string().min(2, 'Name is required'),
  subject:   z.string().min(1, 'Subject is required'),
  category:  z.string().optional(),
});

type FormData = z.infer<typeof templateSchema>;

export const TemplateModal: React.FC<TemplateModalProps> = ({
  isOpen, onClose, onSubmit, initialData,
}) => {
  const isEditing = !!initialData;
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');

  // HTML State
  const [bodyHtml, setBodyHtml] = useState(initialData?.body_html || '');
  const [bodyError, setBodyError] = useState('');

  // Focus Tracking
  const [lastFocus, setLastFocus] = useState<'subject' | 'body'>('body');
  const subjectRef = useRef<HTMLInputElement | null>(null);
  const editorRef = useRef<any>(null); // TipTap instance

  const [standardVars, setStandardVars] = useState<MergeTag[]>([]);
  const [customVars, setCustomVars] = useState<MergeTag[]>([]);

  const {
    register,
    handleSubmit,
    reset,
    setValue,
    watch,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({
    resolver: zodResolver(templateSchema),
    defaultValues: { name: '', subject: '', category: 'custom' },
  });

  const currentSubject = watch('subject');

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        reset({
          name:      initialData.name,
          subject:   initialData.subject,
          category:  initialData.category || 'custom',
        });
        setBodyHtml(initialData.body_html || '');
      } else {
        reset({ name: '', subject: '', category: 'custom' });
        setBodyHtml('');
      }
      setViewMode('edit');

      templateService.getMergeTags()
        .then(res => {
          setStandardVars(res.standard || []);
          const customTags = res.custom || [];
          setCustomVars(customTags.map((tag: string) => ({ tag, label: tag.replace(/[{{}}]/g, '') })));
        })
        .catch(console.error);
    }
  }, [isOpen, initialData, reset]);

  const handleInsert = (tag: string) => {
    if (lastFocus === 'subject' && subjectRef.current) {
      const el = subjectRef.current;
      const start = el.selectionStart ?? el.value.length;
      const end   = el.selectionEnd   ?? el.value.length;
      const newVal = el.value.slice(0, start) + tag + el.value.slice(end);
      setValue('subject', newVal, { shouldDirty: true });
      requestAnimationFrame(() => {
        el.selectionStart = el.selectionEnd = start + tag.length;
        el.focus();
      });
    } else if (editorRef.current) {
      editorRef.current.commands.insertContent(tag);
      editorRef.current.commands.focus();
    }
  };

  const handleSave = async (data: FormData) => {
    if (!bodyHtml || bodyHtml === '<p></p>') {
      setBodyError('HTML Content is required');
      return;
    }
    setBodyError('');
    await onSubmit({ ...data, body_html: bodyHtml });
  };

  const { ref: subjectRHFRef, ...subjectRest } = register('subject');

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-7xl overflow-hidden flex flex-col h-[90vh]">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 bg-white">
          <div className="flex items-center gap-6">
            <h2 className="text-xl font-bold text-gray-900">
              {isEditing ? 'Edit Template' : 'Create Template'}
            </h2>

            <div className="flex bg-gray-100 p-1 rounded-md border border-gray-200">
              <button
                type="button"
                onClick={() => setViewMode('edit')}
                className={`flex items-center gap-2 px-4 py-1.5 rounded-sm text-sm font-medium transition-colors ${viewMode === 'edit' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                <Edit2 size={16} /> Edit
              </button>
              <button
                type="button"
                onClick={() => setViewMode('preview')}
                className={`flex items-center gap-2 px-4 py-1.5 rounded-sm text-sm font-medium transition-colors ${viewMode === 'preview' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                <Eye size={16} /> Preview
              </button>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={onClose}
              disabled={isSubmitting}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 focus:outline-none"
            >
              Cancel
            </button>
            <button
              onClick={handleSubmit(handleSave)}
              disabled={isSubmitting}
              className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 rounded-md hover:bg-indigo-700 focus:outline-none disabled:opacity-50"
            >
              {isSubmitting ? 'Saving...' : 'Save Template'}
            </button>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-700 ml-2">
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        <div className="flex flex-1 overflow-hidden">
          {/* Main Content Area */}
          <div className="flex-1 overflow-y-auto flex flex-col bg-white">
            {viewMode === 'edit' ? (
              <div className="p-6 flex flex-col gap-5 h-full">
                <div className="flex gap-4">
                  <div className="flex-1">
                    <Input
                      label="Template Name *"
                      placeholder="e.g. Q1 Outbound v2"
                      {...register('name')}
                      error={errors.name?.message}
                    />
                  </div>
                  <div className="w-48">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                    <select
                      {...register('category')}
                      className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                      <option value="custom">Custom</option>
                      <option value="cold_outbound">Cold Outbound</option>
                      <option value="follow_up">Follow Up</option>
                    </select>
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="block text-sm font-medium text-gray-700">Email Subject *</label>
                  <input
                    {...subjectRest}
                    ref={(el) => { subjectRHFRef(el); subjectRef.current = el; }}
                    onFocus={() => setLastFocus('subject')}
                    className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    placeholder="{{first_name}}, quick question..."
                  />
                  {errors.subject?.message && <p className="text-sm text-red-500">{errors.subject.message}</p>}
                </div>

                <div className="flex-1 flex flex-col" onClickCapture={() => setLastFocus('body')}>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Email Body *</label>
                  <TipTapEditor
                    content={bodyHtml}
                    onChange={setBodyHtml}
                    editorRef={editorRef}
                  />
                  {bodyError && <p className="text-sm text-red-500 mt-1">{bodyError}</p>}
                </div>
              </div>
            ) : (
              <PreviewPanel subject={currentSubject} bodyHtml={bodyHtml} />
            )}
          </div>

          {/* Sidebar */}
          {viewMode === 'edit' && (
            <PersonalizationSidebar 
              standardVars={standardVars} 
              customVars={customVars} 
              onInsert={handleInsert} 
            />
          )}
        </div>

      </div>
    </div>
  );
};

