import React, { useEffect, useState } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Link from '@tiptap/extension-link';
import Underline from '@tiptap/extension-underline';
import { 
  Bold, Italic, Underline as UnderlineIcon, 
  Strikethrough, List, ListOrdered, Link as LinkIcon,
  Code
} from 'lucide-react';

interface TipTapEditorProps {
  content: string;
  onChange: (content: string) => void;
  editorRef?: React.MutableRefObject<any>;
}

const MenuBar = ({ editor, isSourceMode, setIsSourceMode }: { editor: any, isSourceMode: boolean, setIsSourceMode: (val: boolean) => void }) => {
  if (!editor) {
    return null;
  }

  const setLink = () => {
    const previousUrl = editor.getAttributes('link').href;
    const url = window.prompt('URL', previousUrl);

    // cancelled
    if (url === null) {
      return;
    }

    // empty
    if (url === '') {
      editor.chain().focus().extendMarkRange('link').unsetLink().run();
      return;
    }

    // update link
    editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run();
  };

  return (
    <div className="border-b border-gray-700 bg-gray-900 p-2 flex flex-wrap gap-1 rounded-t-md">
      <button
        type="button"
        onClick={() => editor.chain().focus().toggleBold().run()}
        disabled={!editor.can().chain().focus().toggleBold().run() || isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('bold') ? 'bg-gray-700 text-white' : ''}`}
        title="Bold"
      >
        <Bold size={16} />
      </button>
      <button
        type="button"
        onClick={() => editor.chain().focus().toggleItalic().run()}
        disabled={!editor.can().chain().focus().toggleItalic().run() || isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('italic') ? 'bg-gray-700 text-white' : ''}`}
        title="Italic"
      >
        <Italic size={16} />
      </button>
      <button
        type="button"
        onClick={() => editor.chain().focus().toggleUnderline().run()}
        disabled={!editor.can().chain().focus().toggleUnderline().run() || isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('underline') ? 'bg-gray-700 text-white' : ''}`}
        title="Underline"
      >
        <UnderlineIcon size={16} />
      </button>
      <button
        type="button"
        onClick={() => editor.chain().focus().toggleStrike().run()}
        disabled={!editor.can().chain().focus().toggleStrike().run() || isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('strike') ? 'bg-gray-700 text-white' : ''}`}
        title="Strikethrough"
      >
        <Strikethrough size={16} />
      </button>

      <div className="w-px h-6 bg-gray-700 mx-1 self-center" />

      <button
        type="button"
        onClick={() => editor.chain().focus().toggleBulletList().run()}
        disabled={isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('bulletList') ? 'bg-gray-700 text-white' : ''}`}
        title="Bullet List"
      >
        <List size={16} />
      </button>
      <button
        type="button"
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
        disabled={isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('orderedList') ? 'bg-gray-700 text-white' : ''}`}
        title="Ordered List"
      >
        <ListOrdered size={16} />
      </button>

      <div className="w-px h-6 bg-gray-700 mx-1 self-center" />

      <button
        type="button"
        onClick={setLink}
        disabled={isSourceMode}
        className={`p-1.5 rounded hover:bg-gray-700 text-gray-300 transition-colors ${editor.isActive('link') ? 'bg-gray-700 text-white' : ''}`}
        title="Add Link"
      >
        <LinkIcon size={16} />
      </button>

      <div className="flex-1" />

      <button
        type="button"
        onClick={() => setIsSourceMode(!isSourceMode)}
        className={`flex items-center gap-1 px-2 py-1 rounded text-sm font-medium transition-colors ${isSourceMode ? 'bg-blue-600/20 text-blue-400' : 'hover:bg-gray-700 text-gray-300'}`}
        title="Toggle HTML Source"
      >
        <Code size={16} />
        {isSourceMode ? 'Source' : 'Rich Text'}
      </button>
    </div>
  );
};

export const TipTapEditor: React.FC<TipTapEditorProps> = ({ content, onChange, editorRef }) => {
  const [isSourceMode, setIsSourceMode] = useState(false);
  const [htmlContent, setHtmlContent] = useState(content);

  const editor = useEditor({
    extensions: [
      StarterKit,
      Underline,
      Link.configure({
        openOnClick: false,
        HTMLAttributes: {
          class: 'text-blue-400 hover:underline cursor-pointer',
        },
      }),
    ],
    content: content,
    onUpdate: ({ editor }) => {
      const html = editor.getHTML();
      setHtmlContent(html);
      onChange(html);
    },
    editorProps: {
      attributes: {
        class: 'prose prose-invert max-w-none p-4 min-h-[300px] focus:outline-none focus:ring-0',
      },
    },
  });

  // Expose editor instance
  useEffect(() => {
    if (editorRef) {
      editorRef.current = editor;
    }
  }, [editor, editorRef]);

  // Handle external content updates (when switching modes or opening existing templates)
  useEffect(() => {
    if (editor && content !== editor.getHTML()) {
      editor.commands.setContent(content, false);
      setHtmlContent(content);
    }
  }, [content, editor]);

  const handleSourceChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    setHtmlContent(val);
    onChange(val);
    if (editor) {
      editor.commands.setContent(val, false);
    }
  };

  return (
    <div className="flex flex-col border border-gray-700 rounded-md bg-gray-800 shadow-sm overflow-hidden">
      <MenuBar editor={editor} isSourceMode={isSourceMode} setIsSourceMode={setIsSourceMode} />

      <div className="relative flex-1 min-h-[300px] bg-gray-900 overflow-y-auto">
        {isSourceMode ? (
          <textarea
            value={htmlContent}
            onChange={handleSourceChange}
            className="absolute inset-0 w-full h-full p-4 bg-gray-900 text-gray-300 font-mono text-sm focus:outline-none resize-none"
            spellCheck={false}
          />
        ) : (
          <EditorContent editor={editor} />
        )}
      </div>
    </div>
  );
};
